package com.clavis.reader;
import java.util.*;
public final class BookDeletionChecks {
 static int checks;static void check(boolean ok){checks++;if(!ok)throw new AssertionError("Deletion check "+checks);}
 public static void main(String[] args){Book pdf=new Book("file:///tmp/book.pdf","PDF","PDF");check(BookDeletionPlan.files(pdf,Arrays.asList(pdf)).size()==1);Book audio=new Book("content://docs/tree/root/document/root%2FBook","Audio","Audio");audio.chapters.add(new Book.Chapter("content://docs/tree/root/document/root%2FBook%2F1.mp3","First"));audio.chapters.add(new Book.Chapter("content://docs/tree/root/document/root%2FBook%2F2.mp3","Second"));audio.chapters.add(new Book.Chapter("content://docs/tree/root/document/root%2FBook%2F2.mp3","Duplicate"));audio.coverUri="content://docs/tree/root/document/root%2Fcover.jpg";check(BookDeletionPlan.files(audio,Arrays.asList(audio)).size()==3);check(!BookDeletionPlan.files(audio,Arrays.asList(audio)).contains(audio.uri));Book other=new Book("other","Other","Audio");other.coverUri="content://docs/tree/root%2FOther/document/root%2Fcover.jpg";check(BookDeletionPlan.files(audio,Arrays.asList(audio,other)).size()==2);other.chapters.add(new Book.Chapter("content://docs/tree/another/document/root%2FBook%2F1.mp3","Shared"));check(BookDeletionPlan.files(audio,Arrays.asList(audio,other)).size()==1);check(BookDeletionPlan.key("file:///tmp/a/../book.pdf").equals(BookDeletionPlan.key(pdf.uri)));check(BookDeletionPlan.key("content://docs/tree/a/document/root%2Fx").equals(BookDeletionPlan.key("content://docs/tree/b/document/root%2Fx")));System.out.println(checks+" deletion planning checks passed");}
}
